45	export interface RadarIndicatorOption {
46	    name?: string
47	    /**
48	     * @deprecated Use `name` instead.
49	     */
50	    text?: string
51	    min?: number
52	    max?: number
53	    color?: ColorString
54	
55	    axisType?: 'value' | 'log'
56	}
57	
58	export interface RadarOption extends ComponentOption, CircleLayoutOptionMixin {
59	    mainType?: 'radar'
60	
61	    startAngle?: number
62	
63	    clockwise?: boolean
64	
65	    shape?: 'polygon' | 'circle'
66	
67	    // TODO. axisType seems to have issue.
68	    // axisType?: 'value' | 'log'
69	
70	    axisLine?: AxisBaseOption['axisLine']
71	    axisTick?: AxisBaseOption['axisTick']
72	    axisLabel?: AxisBaseOption['axisLabel']
73	    splitLine?: AxisBaseOption['splitLine']
74	    splitArea?: AxisBaseOption['splitArea']
75	
76	    // TODO Use axisName?
77	    axisName?: {
78	        show?: boolean
79	        formatter?: string | ((name?: string, indicatorOpt?: InnerIndicatorAxisOption) => string)
80	    } & LabelOption
81	    axisNameGap?: number
82	
83	    triggerEvent?: boolean
84	
85	    scale?: boolean
86	    splitNumber?: number
87	
88	    boundaryGap?: CategoryAxisBaseOption['boundaryGap']
89	        | ValueAxisBaseOption['boundaryGap']
90	
91	    indicator?: RadarIndicatorOption[]
92	}
