94	export type InnerIndicatorAxisOption = AxisBaseOption & {
95	    // TODO Use type?
96	    // axisType?: 'value' | 'log'
97	    showName?: boolean
98	};
99	
100	class RadarModel extends ComponentModel<RadarOption> implements CoordinateSystemHostModel {
101	    static readonly type = 'radar';
102	    readonly type = RadarModel.type;
103	
104	    coordinateSystem: Radar;
105	
106	    private _indicatorModels: AxisBaseModel<InnerIndicatorAxisOption>[];
107	
108	    optionUpdated() {
109	        const boundaryGap = this.get('boundaryGap');
110	        const splitNumber = this.get('splitNumber');
111	        const clockwise = this.get('clockwise');
112	        const scale = this.get('scale');
113	        const axisLine = this.get('axisLine');
114	        const axisTick = this.get('axisTick');
115	        // let axisType = this.get('axisType');
116	        const axisLabel = this.get('axisLabel');
117	        const nameTextStyle = this.get('axisName');
118	        const showName = this.get(['axisName', 'show']);
119	        const nameFormatter = this.get(['axisName', 'formatter']);
120	        const nameGap = this.get('axisNameGap');
121	        const triggerEvent = this.get('triggerEvent');
122	
123	        const indicatorModels = zrUtil.map(this.get('indicator') || [], function (indicatorOpt) {
124	            // PENDING
125	            if (indicatorOpt.max != null && indicatorOpt.max > 0 && !indicatorOpt.min) {
126	                indicatorOpt.min = 0;
127	            }
128	            else if (indicatorOpt.min != null && indicatorOpt.min < 0 && !indicatorOpt.max) {
129	                indicatorOpt.max = 0;
130	            }
131	            let iNameTextStyle = nameTextStyle;
132	            if (indicatorOpt.color != null) {
133	                iNameTextStyle = zrUtil.defaults({
134	                    color: indicatorOpt.color
135	                }, nameTextStyle);
136	            }
137	            // Use same configuration
138	            const innerIndicatorOpt: InnerIndicatorAxisOption = zrUtil.merge(zrUtil.clone(indicatorOpt), {
139	                boundaryGap: boundaryGap,
140	                splitNumber: splitNumber,
141	                clockwise: clockwise,
142	                scale: scale,
143	                axisLine: axisLine,
144	                axisTick: axisTick,
145	                // axisType: axisType,
146	                axisLabel: axisLabel,
147	                // Compatible with 2 and use text
148	                name: indicatorOpt.text,
149	                showName: showName,
150	                nameLocation: 'end',
151	                nameGap: nameGap,
152	                // min: 0,
153	                nameTextStyle: iNameTextStyle,
154	                triggerEvent: triggerEvent
155	            } as InnerIndicatorAxisOption, false);
156	            if (zrUtil.isString(nameFormatter)) {
157	                const indName = innerIndicatorOpt.name;
158	                innerIndicatorOpt.name = nameFormatter.replace('{value}', indName != null ? indName : '');
159	            }
160	            else if (zrUtil.isFunction(nameFormatter)) {
161	                innerIndicatorOpt.name = nameFormatter(
162	                    innerIndicatorOpt.name, innerIndicatorOpt
163	                );
164	            }
165	
166	            const model = new Model(innerIndicatorOpt, null, this.ecModel) as AxisBaseModel<InnerIndicatorAxisOption>;
167	            zrUtil.mixin(model, AxisModelCommonMixin.prototype);
168	            // For triggerEvent.
169	            model.mainType = 'radar';
170	            model.componentIndex = this.componentIndex;
171	
172	            return model;
173	        }, this);
174	
175	        this._indicatorModels = indicatorModels;
176	    }
177	
178	    getIndicatorModels() {
179	        return this._indicatorModels;
180	    }
181	
182	    static defaultOption: RadarOption = {
183	
184	        // zlevel: 0,
185	
186	        z: 0,
187	
188	        center: ['50%', '50%'],
189	
190	        radius: '50%',
191	
192	        startAngle: 90,
193	
194	        clockwise: false,
195	
196	        axisName: {
197	            show: true,
198	            color: tokens.color.axisLabel
199	            // formatter: null
200	            // textStyle: {}
201	        },
202	
203	        boundaryGap: [0, 0],
204	
205	        splitNumber: 5,
206	
207	        axisNameGap: 15,
208	
209	        scale: false,
210	
211	        // Polygon or circle
212	        shape: 'polygon',
213	
214	        axisLine: zrUtil.merge(
215	            {
216	                lineStyle: {
217	                    color: tokens.color.neutral20
218	                }
219	            },
220	            valueAxisDefault.axisLine
221	        ),
222	        axisLabel: defaultsShow(valueAxisDefault.axisLabel, false),
223	        axisTick: defaultsShow(valueAxisDefault.axisTick, false),
224	        // axisType: 'value',
225	        splitLine: defaultsShow(valueAxisDefault.splitLine, true),
226	        splitArea: defaultsShow(valueAxisDefault.splitArea, true),
227	
228	        // {text, min, max}
229	        indicator: []
230	    };
231	}
