20	import * as zrUtil from 'zrender/src/core/util';
21	import Scale, { ScaleGetTicksOpt } from './Scale';
22	import * as numberUtil from '../util/number';
23	
24	// Use some method of IntervalScale
25	import IntervalScale from './Interval';
26	import {
27	    DimensionLoose, DimensionName, ParsedAxisBreakList, AxisBreakOption,
28	    ScaleTick
29	} from '../util/types';
30	import { getIntervalPrecision, logTransform } from './helper';
31	import SeriesData from '../data/SeriesData';
32	import { getScaleBreakHelper } from './break';
33	
34	const fixRound = numberUtil.round;
35	const mathFloor = Math.floor;
36	const mathCeil = Math.ceil;
37	const mathPow = Math.pow;
38	const mathLog = Math.log;
39	
40	class LogScale extends IntervalScale {
41	
42	    static type = 'log';
43	    readonly type = 'log';
44	
45	    base = 10;
46	
47	    private _originalScale = new IntervalScale();
48	
49	    private _fixMin: boolean;
50	    private _fixMax: boolean;
51	
52	    /**
53	     * @param Whether expand the ticks to niced extent.
54	     */
55	    getTicks(opt?: ScaleGetTicksOpt): ScaleTick[] {
56	        opt = opt || {};
57	        const extent = this._extent.slice() as [number, number];
58	        const originalExtent = this._originalScale.getExtent();
59	
60	        const ticks = super.getTicks(opt);
61	        const base = this.base;
62	        const originalBreaks = this._originalScale._innerGetBreaks();
63	        const scaleBreakHelper = getScaleBreakHelper();
64	
65	        return zrUtil.map(ticks, function (tick) {
66	            const val = tick.value;
67	            let roundingCriterion = null;
68	
69	            let powVal = mathPow(base, val);
70	
71	            // Fix #4158
72	            if (val === extent[0] && this._fixMin) {
73	                roundingCriterion = originalExtent[0];
74	            }
75	            else if (val === extent[1] && this._fixMax) {
76	                roundingCriterion = originalExtent[1];
77	            }
78	
79	            let vBreak;
80	            if (scaleBreakHelper) {
81	                const transformed = scaleBreakHelper.getTicksLogTransformBreak(
82	                    tick,
83	                    base,
84	                    originalBreaks,
85	                    fixRoundingError
86	                );
87	                vBreak = transformed.vBreak;
88	                if (roundingCriterion == null) {
89	                    roundingCriterion = transformed.brkRoundingCriterion;
90	                }
91	            }
92	
93	            if (roundingCriterion != null) {
94	                powVal = fixRoundingError(powVal, roundingCriterion);
95	            }
96	
97	            return {
98	                value: powVal,
99	                break: vBreak,
100	            };
101	        }, this);
102	    }
103	
104	    protected _getNonTransBreaks(): ParsedAxisBreakList {
105	        return this._originalScale._innerGetBreaks();
106	    }
107	
108	    setExtent(start: number, end: number): void {
109	        this._originalScale.setExtent(start, end);
110	        const loggedExtent = logTransform(this.base, [start, end]);
111	        super.setExtent(loggedExtent[0], loggedExtent[1]);
112	    }
113	
114	    /**
115	     * @return {number} end
116	     */
117	    getExtent() {
118	        const base = this.base;
119	        const extent = super.getExtent();
120	        extent[0] = mathPow(base, extent[0]);
121	        extent[1] = mathPow(base, extent[1]);
122	
123	        // Fix #4158
124	        const originalExtent = this._originalScale.getExtent();
125	        this._fixMin && (extent[0] = fixRoundingError(extent[0], originalExtent[0]));
126	        this._fixMax && (extent[1] = fixRoundingError(extent[1], originalExtent[1]));
127	
128	        return extent;
129	    }
130	
131	    unionExtentFromData(data: SeriesData, dim: DimensionName | DimensionLoose): void {
132	        this._originalScale.unionExtentFromData(data, dim);
133	        const loggedOther = logTransform(this.base, data.getApproximateExtent(dim), true);
134	        this._innerUnionExtent(loggedOther);
135	    }
136	
137	    /**
138	     * Update interval and extent of intervals for nice ticks
139	     * @param approxTickNum default 10 Given approx tick number
140	     */
141	    calcNiceTicks(approxTickNum: number): void {
142	        approxTickNum = approxTickNum || 10;
143	        const extent = this._extent.slice() as [number, number];
144	        const span = this._getExtentSpanWithBreaks();
145	        if (!isFinite(span) || span <= 0) {
146	            return;
147	        }
148	
149	        let interval = numberUtil.quantity(span);
150	        const err = approxTickNum / span * interval;
151	
152	        // Filter ticks to get closer to the desired count.
153	        if (err <= 0.5) {
154	            interval *= 10;
155	        }
156	
157	        // Interval should be integer
158	        while (!isNaN(interval) && Math.abs(interval) < 1 && Math.abs(interval) > 0) {
159	            interval *= 10;
160	        }
161	
162	        const niceExtent = [
163	            fixRound(mathCeil(extent[0] / interval) * interval),
164	            fixRound(mathFloor(extent[1] / interval) * interval)
165	        ] as [number, number];
166	
167	        this._interval = interval;
168	        this._intervalPrecision = getIntervalPrecision(interval);
169	        this._niceExtent = niceExtent;
170	    }
171	
172	    calcNiceExtent(opt: {
173	        splitNumber: number,
174	        fixMin?: boolean,
175	        fixMax?: boolean,
176	        minInterval?: number,
177	        maxInterval?: number
178	    }): void {
179	        super.calcNiceExtent(opt);
180	
181	        this._fixMin = opt.fixMin;
182	        this._fixMax = opt.fixMax;
183	    }
184	
185	    contain(val: number): boolean {
186	        val = mathLog(val) / mathLog(this.base);
187	        return super.contain(val);
188	    }
189	
190	    normalize(val: number): number {
191	        val = mathLog(val) / mathLog(this.base);
192	        return super.normalize(val);
193	    }
194	
195	    scale(val: number): number {
196	        val = super.scale(val);
197	        return mathPow(this.base, val);
198	    }
199	
200	    setBreaksFromOption(
201	        breakOptionList: AxisBreakOption[],
202	    ): void {
203	        const scaleBreakHelper = getScaleBreakHelper();
204	        if (!scaleBreakHelper) {
205	            return;
206	        }
207	        const {parsedOriginal, parsedLogged} = scaleBreakHelper.logarithmicParseBreaksFromOption(
208	            breakOptionList,
209	            this.base,
210	            zrUtil.bind(this.parse, this)
211	        );
212	        this._originalScale._innerSetBreak(parsedOriginal);
213	        this._innerSetBreak(parsedLogged);
214	    }
215	
216	}
217	
218	function fixRoundingError(val: number, originalVal: number): number {
219	    return fixRound(val, numberUtil.getPrecision(originalVal));
220	}
221	
222	
223	Scale.registerClass(LogScale);
224	
225	export default LogScale;

