623	function isCoordInLayoutInfo(coord: number, cell: MatrixCellLayoutInfo): boolean {
624	    return cell.xy <= coord && coord <= cell.xy + cell.wh;
625	}
626	function isCoordInRect(coord: number, rect: RectLike, dimIdx: number): boolean {
627	    return rect[XY[dimIdx]] <= coord && coord <= rect[XY[dimIdx]] + rect[WH[dimIdx]];
628	}
