182	/**
183	 * Get precision.
184	 */
185	export function getPrecision(val: string | number): number {
186	    val = +val;
187	    if (isNaN(val)) {
188	        return 0;
189	    }
190	
191	    // It is much faster than methods converting number to string as follows
192	    //      let tmp = val.toString();
193	    //      return tmp.length - 1 - tmp.indexOf('.');
194	    // especially when precision is low
195	    // Notice:
196	    // (1) If the loop count is over about 20, it is slower than `getPrecisionSafe`.
197	    //     (see https://jsbench.me/2vkpcekkvw/1)
198	    // (2) If the val is less than for example 1e-15, the result may be incorrect.
199	    //     (see test/ut/spec/util/number.test.ts `getPrecision_equal_random`)
200	    if (val > 1e-14) {
201	        let e = 1;
202	        for (let i = 0; i < 15; i++, e *= 10) {
203	            if (Math.round(val * e) / e === val) {
204	                return i;
205	            }
206	        }
207	    }
208	
209	    return getPrecisionSafe(val);
210	}
211	
212	/**
213	 * Get precision with slow but safe method
214	 */
215	export function getPrecisionSafe(val: string | number): number {
216	    // toLowerCase for: '3.4E-12'
217	    const str = val.toString().toLowerCase();
218	
219	    // Consider scientific notation: '3.4e-12' '3.4e+12'
220	    const eIndex = str.indexOf('e');
221	    const exp = eIndex > 0 ? +str.slice(eIndex + 1) : 0;
222	    const significandPartLen = eIndex > 0 ? eIndex : str.length;
223	    const dotIndex = str.indexOf('.');
224	    const decimalPartLen = dotIndex < 0 ? 0 : significandPartLen - 1 - dotIndex;
225	    return Math.max(0, decimalPartLen - exp);
226	}
