228	/**
229	 * Minimal dicernible data precisioin according to a single pixel.
230	 */
231	export function getPixelPrecision(dataExtent: [number, number], pixelExtent: [number, number]): number {
232	    const log = Math.log;
233	    const LN10 = Math.LN10;
234	    const dataQuantity = Math.floor(log(dataExtent[1] - dataExtent[0]) / LN10);
235	    const sizeQuantity = Math.round(log(mathAbs(pixelExtent[1] - pixelExtent[0])) / LN10);
236	    // toFixed() digits argument must be between 0 and 20.
237	    const precision = Math.min(Math.max(-dataQuantity + sizeQuantity, 0), 20);
238	    return !isFinite(precision) ? 20 : precision;
239	}

