67	        const radar = radarModel.coordinateSystem;
68	        const indicatorAxes = radar.getIndicatorAxes();
69	        if (!indicatorAxes.length) {
70	            return;
71	        }
72	        const shape = radarModel.get('shape');
73	        const splitLineModel = radarModel.getModel('splitLine');
74	        const splitAreaModel = radarModel.getModel('splitArea');
75	        const lineStyleModel = splitLineModel.getModel('lineStyle');
76	        const areaStyleModel = splitAreaModel.getModel('areaStyle');
77	
78	        const showSplitLine = splitLineModel.get('show');
79	        const showSplitArea = splitAreaModel.get('show');
80	        const splitLineColors = lineStyleModel.get('color');
81	        const splitAreaColors = areaStyleModel.get('color');
82	
83	        const splitLineColorsArr = zrUtil.isArray(splitLineColors) ? splitLineColors : [splitLineColors];
84	        const splitAreaColorsArr = zrUtil.isArray(splitAreaColors) ? splitAreaColors : [splitAreaColors];
85	
86	        const splitLines: (graphic.Circle | graphic.Polyline)[][] = [];
87	        const splitAreas: (graphic.Ring | graphic.Polygon)[][] = [];
88	
89	        function getColorIndex(
90	            areaOrLine: any[][],
91	            areaOrLineColorList: ZRColor[],
92	            idx: number
93	        ) {
94	            const colorIndex = idx % areaOrLineColorList.length;
95	            areaOrLine[colorIndex] = areaOrLine[colorIndex] || [];
96	            return colorIndex;
97	        }
98	
99	        if (shape === 'circle') {
100	            const ticksRadius = indicatorAxes[0].getTicksCoords();
101	            const cx = radar.cx;
102	            const cy = radar.cy;
103	            for (let i = 0; i < ticksRadius.length; i++) {
104	                if (showSplitLine) {
105	                    const colorIndex = getColorIndex(splitLines, splitLineColorsArr, i);
106	                    splitLines[colorIndex].push(new graphic.Circle({
107	                        shape: {
108	                            cx: cx,
109	                            cy: cy,
110	                            r: ticksRadius[i].coord
111	                        }
112	                    }));
113	                }
114	                if (showSplitArea && i < ticksRadius.length - 1) {
115	                    const colorIndex = getColorIndex(splitAreas, splitAreaColorsArr, i);
116	                    splitAreas[colorIndex].push(new graphic.Ring({
117	                        shape: {
118	                            cx: cx,
119	                            cy: cy,
120	                            r0: ticksRadius[i].coord,
121	                            r: ticksRadius[i + 1].coord
122	                        }
123	                    }));
124	                }
125	            }
126	        }
127	        // Polyyon
128	        else {
129	            let realSplitNumber: number;
130	            const axesTicksPoints = zrUtil.map(indicatorAxes, function (indicatorAxis, idx) {
131	                const ticksCoords = indicatorAxis.getTicksCoords();
132	                realSplitNumber = realSplitNumber == null
133	                    ? ticksCoords.length - 1
134	                    : Math.min(ticksCoords.length - 1, realSplitNumber);
135	                return zrUtil.map(ticksCoords, function (tickCoord) {
136	                    return radar.coordToPoint(tickCoord.coord, idx);
137	                });
138	            });
139	
140	            let prevPoints: number[][] = [];
141	            for (let i = 0; i <= realSplitNumber; i++) {
142	                const points: number[][] = [];
143	                for (let j = 0; j < indicatorAxes.length; j++) {
144	                    points.push(axesTicksPoints[j][i]);
145	                }
146	                // Close
147	                if (points[0]) {
148	                    points.push(points[0].slice());
149	                }
150	                else {
151	                    if (__DEV__) {
152	                        console.error('Can\'t draw value axis ' + i);
153	                    }
154	                }
155	
156	                if (showSplitLine) {
157	                    const colorIndex = getColorIndex(splitLines, splitLineColorsArr, i);
158	                    splitLines[colorIndex].push(new graphic.Polyline({
159	                        shape: {
160	                            points: points
161	                        }
162	                    }));
163	                }
164	                if (showSplitArea && prevPoints) {
165	                    const colorIndex = getColorIndex(splitAreas, splitAreaColorsArr, i - 1);
166	                    splitAreas[colorIndex].push(new graphic.Polygon({
167	                        shape: {
168	                            points: points.concat(prevPoints)
169	                        }
170	                    }));
171	                }
172	                prevPoints = points.slice().reverse();
173	            }
174	        }
175	
176	        const lineStyle = lineStyleModel.getLineStyle();
177	        const areaStyle = areaStyleModel.getAreaStyle();
178	        // Add splitArea before splitLine
179	        zrUtil.each(splitAreas, function (splitAreas, idx) {
180	            this.group.add(graphic.mergePath(
181	                splitAreas, {
182	                    style: zrUtil.defaults({
183	                        stroke: 'none',
184	                        fill: splitAreaColorsArr[idx % splitAreaColorsArr.length]
185	                    }, areaStyle),
186	                    silent: true
187	                }
188	            ));
189	        }, this);
190	
191	        zrUtil.each(splitLines, function (splitLines, idx) {
192	            this.group.add(graphic.mergePath(
193	                splitLines, {
194	                    style: zrUtil.defaults({
195	                        fill: 'none',
196	                        stroke: splitLineColorsArr[idx % splitLineColorsArr.length]
197	                    }, lineStyle),
198	                    silent: true
199	                }
200	            ));
201	        }, this);
202	
203	    }
204	}
